@zk_circuit
def kernel(a: Float[Array, '5']):
    vals, idx = np.unique(a, return_inverse=True)
    b = np.zeros((a.size, vals.size))
    b[np.arange(a.size), idx] = 1
    return b

@zk_circuit
@requires(lambda a: np.unique(a).size == 3)
def kernel(a: Float[Array, '5']):
    vals, idx = np.unique(a, return_inverse=True)
    b = np.zeros((a.size, vals.size))
    b[np.arange(a.size), idx] = 1
    return b

@zk_circuit
def kernel(A: Float[Array, '23'], ncol: Integer):
    col = A.shape[0] // ncol * ncol
    B = A[:col]
    B = np.reshape(B, (-1, ncol))
    return B

@zk_circuit
@requires(lambda A, ncol: ncol == 5)
def kernel(A: Float[Array, '23'], ncol: Integer):
    col = A.shape[0] // ncol * ncol
    B = A[:col]
    B = np.reshape(B, (-1, ncol))
    return B

